SELECT "YaleLanguages_2"."Calculation_1810108111146429" AS "Calculation_1810108111146429",   SUM(CAST("YaleLanguages_2"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok",   CAST(EXTRACT(YEAR FROM "YaleLanguages_2"."CHARGE_DATE") AS BIGINT) AS "yr_CHARGE_DATE_ok" FROM "YaleLanguages_2" WHERE ((CAST("YaleLanguages_2"."CHARGE_DATE" as DATE) >= cast('2002-01-01' as DATE)) AND ("YaleLanguages_2"."PATRON_TYPE__Pseudo_vs_Patron_" = 'Patron')) GROUP BY "Calculation_1810108111146429",   "yr_CHARGE_DATE_ok";
